pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(uint256 fuzzBlockNumber, uint256 fuzzTimestamp) public {
        uint256 bn = bound(fuzzBlockNumber, 1, type(uint64).max);
        uint256 ts = bound(fuzzTimestamp, 1, type(uint64).max);

        address actor = address(0xABCD);
        vm.deal(actor, 20 ether);

        vm.warp(ts);
        vm.roll(bn);

        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}('');
        require(ok, "fallback call failed unexpectedly");

        bool isMultipleOf15 = (block.number % 15 == 0);
        assertTrue((address(c).balance == 0) == isMultipleOf15);
    }
}
